INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (12,12,'["Pouvez-vous nous expliquer ce que vous comprenez du rôle d''un assistant architecte au sein d''un organisme de développement régional ?", "Avez-vous des notions de base en lecture de plans architecturaux ou en logiciels comme AutoCAD ou SketchUp, même dans un cadre scolaire ou personnel ?", "Quelle est, selon vous, la différence entre un permis de construire et une autorisation de lotir, et à quoi servent-ils ?", "Votre diplôme est en Informatique et Intelligence Artificielle — qu''est-ce qui vous a amené à postuler pour un poste d''Assistant Architecte ?", "Durant votre formation au lycée Al Khawarizmi, avez-vous réalisé des projets ou travaux en lien avec la conception, la modélisation ou l''urbanisme ?", "En dehors de votre cursus scolaire, avez-vous entrepris des formations complémentaires, des stages ou des auto-apprentissages en rapport avec l''architecture ou le bâtiment ?", "Pourquoi souhaitez-vous intégrer le secteur de l''architecture et de l''aménagement du territoire plutôt que de poursuivre dans votre domaine de formation initial ?", "Où vous voyez-vous professionnellement dans 3 à 5 ans, et comment ce poste s''inscrit-il dans ce parcours ?", "Que savez-vous des missions principales de l''Agence de Développement Régional Fès-Meknès et des projets qu''elle pilote dans la région ?", "Selon vous, quelles sont les contraintes spécifiques du travail dans un établissement public par rapport au secteur privé ?"]','[]','{}','2026-08-27 13:27:53.307849') ON CONFLICT (id) DO NOTHING;